"""Data-only identities and append-once evidence for the owned scalar slice."""
import hashlib
import json
from pathlib import Path

BASE = Path('docs/audits/observer-scalar-values-20261010')
CENSUS = Path('docs/audits/observer-header-source-census-20261010')
PREDICATE = Path('docs/audits/observer-predicate-values-20261010')
REVISION = 'fa40d54b364b9afa87342de0084f2ed8e9214794'
SCOPE = ('Complete source scalar values and selected current public scalar constructors only. '
         'Inherited serialized inner operands retain their dated evidence role; they are not '
         'a new independent semantic header oracle. Original scalar flags, formatter/settings, '
         'reference/receiver/referent identity, private framework intervals and do/require '
         'roles remain unchanged. Regex, full original headers and parent acceptance stay open.')


def need(condition, cause):
    if not condition:
        raise ValueError(cause)


def canonical(value):
    return (json.dumps(value, sort_keys=True, separators=(',', ':'), ensure_ascii=True,
                       allow_nan=False) + '\n').encode()


def same(left, right):
    return canonical(left) == canonical(right)


def pin(raw):
    return dict(bytes=len(raw), sha256=hashlib.sha256(raw).hexdigest())


def read(path):
    return json.loads(path.read_bytes())


def load(name):
    return read(BASE / name)


def save(name, value):
    path = BASE / name
    need(not path.exists(), 'retain first complete evidence: ' + name)
    path.write_bytes(canonical(value))


def module(path):
    namespace = {'__name__': 'scalar_source_dependency', '__file__': str(path)}
    exec(compile(path.read_bytes(), str(path), 'exec'), namespace)
    return namespace

"""Derive whole scalar membership and finite recipes before native observation."""
from pathlib import Path
from common import BASE, CENSUS, SCOPE, canonical, module, need, pin, read, save


def source():
    classes = module(Path('docs/audits/record-value-original-class-20261005/verify.py'))
    public = module(Path('docs/audits/record-value-public-boundary-join-20261006/verify.py'))
    builder = module(Path('docs/audits/record-value-class-frame-join-20261006/model.py'))
    actual = builder['derive'](classes, public, classes['require'], classes['same'])
    need(canonical(actual) == canonical(read(CENSUS / 'source-models.json')),
         'complete qualified own-source model rederived before scalar selection')
    return actual


def collect(census):
    values, members = {}, []
    for row in census['operands']:
        if row['schema'] not in ('scalar', 'context_scalar') or row['input']['role'] == 'guard predicate':
            continue
        operand = row['input']
        value = operand['value' if row['schema'] == 'scalar' else 'source_value']
        need(value is None or type(value) in (str, int), 'complete typed source scalar')
        identifier = pin(canonical(value))['sha256']
        values[identifier] = dict(value=value, constructor=('undef' if value is None else
            'numeric literal' if type(value) is int else 'complete codepoint string'))
        members.append(dict(path=row['path'], schema=row['schema'], operand=operand, value=identifier,
            evidence_role=('inherited serialized evidence' if operand['role'] == 'entire_context_and_inner_error'
                           else 'qualified own-source value')))
    return dict(scope=SCOPE, values=values, members=members)


def display(value, limit):
    if value is None:
        return dict(token='undef', complete=True, prefix=None)
    if type(value) is int:
        return dict(token=str(value), complete=True, prefix=str(value))
    # The complete current corpus contains only these finite numeric-looking
    # string forms. No general numeric conversion contract is inferred.
    numeric = value in ('0', '1', '2')
    shortened = not numeric and limit >= 3 and len(value) > limit
    prefix = value[:limit - 3] if shortened else value
    escaped = ''.join('\\x{' + format(ord(c), 'x') + '}' if ord(c) < 32 or ord(c) >= 127
                      else '\\' + c if c in '\\"$@' else c for c in prefix)
    token = prefix if numeric else '"' + escaped + '"' + ('...' if shortened else '')
    return dict(token=token, complete=not shortened, prefix=prefix)


def plan(product):
    cases = []
    for identifier, item in sorted(product['values'].items()):
        for limit in (64, 0):
            cases.append(dict(id=identifier + ':' + str(limit), value_id=identifier,
                value=item['value'], constructor=item['constructor'], limit=limit,
                display=display(item['value'], limit)))
    return dict(scope=SCOPE, profile=dict(MaxArgNums=0, MaxEvalLen=0, RefArgFormatter=None), cases=cases)


def main():
    source()
    product = collect(read(CENSUS / 'census.json'))
    save('scalars.json', product)
    save('plan.json', plan(product))
    save('pre-observation.json', dict(inputs={str(p):pin(p.read_bytes()) for p in
         [CENSUS / 'census.json', CENSUS / 'source-models.json', *sorted(BASE.glob('*.py')),
          BASE / 'native.pl', BASE / 'scalars.json', BASE / 'plan.json']},
         scope=SCOPE, native_present=(BASE / 'native.json').exists()))
    need(not (BASE / 'native.json').exists(), 'source selection precedes native observation')
    print('PASS complete source scalar selection and current display hypotheses before native capture.')


if __name__ == '__main__':
    main()

use v5.20;
use strict;
use warnings;
use Carp ();
use JSON::PP ();
local $Carp::MaxArgNums = 0;
local $Carp::MaxEvalLen = 0;
local $Carp::RefArgFormatter = undef;
sub emitter { return Carp::longmess('scalar source fixture') }
sub boundary {
    my ($value) = @_;
    my $trace = emitter();
    return {trace => $trace, value => {defined => defined($value) ? JSON::PP::true : JSON::PP::false,
        codepoints => defined($value) ? [unpack 'U*', "$value"] : []}};
}
open my $input, '<', 'docs/audits/observer-scalar-values-20261010/plan.json' or die $!;
local $/;
my $plan = JSON::PP->new->decode(<$input>);
close $input or die $!;
my @rows;
for my $case (@{$plan->{cases}}) {
    local $Carp::MaxArgLen = $case->{limit};
    my $value = !defined($case->{value}) ? undef : $case->{constructor} eq 'numeric literal' ? 0 + $case->{value}
        : pack 'U*', map {ord} split //, $case->{value};
    my $row = boundary($value);
    $row->{id} = $case->{id};
    $row->{profile} = {MaxArgLen => $Carp::MaxArgLen, MaxArgNums => $Carp::MaxArgNums,
        MaxEvalLen => $Carp::MaxEvalLen, RefArgFormatter => undef};
    push @rows, $row;
}
print JSON::PP->new->canonical->encode({rows => \@rows,
    runtime => {perl => "$^V", carp => "$Carp::VERSION", json_pp => "$JSON::PP::VERSION"}}), "\n";

"""Independent source traversal and whole scalar/current-native reconstruction."""
import re
from common import SCOPE, canonical, need, pin, same


def source_members(source):
    # Traverse the complete source model directly, never the producer census.
    # Reversed stack insertion preserves its sorted structural traversal.
    pending = [(source['modes'], ['modes'])]
    result = []
    while pending:
        value, path = pending.pop()
        if type(value) is list:
            pending.extend((value[i], path + [i]) for i in reversed(range(len(value))))
        elif type(value) is dict:
            if 'role' in value and (value.get('kind') == 'scalar' or 'source_value' in value):
                if value['role'] != 'guard predicate':
                    context = 'source_value' in value
                    expected_keys = ({'expression', 'match', 'native_scalar_encoding', 'position', 'role', 'source_value'}
                        if context else {'kind', 'role', 'value'})
                    need(set(value) == expected_keys, 'independent closed scalar schema')
                    if context:
                        need(value['native_scalar_encoding'] == 'not measured', 'original scalar flags remain unmeasured')
                    raw = value['source_value' if context else 'value']
                    need(raw is None or type(raw) in (int, str), 'independent exact scalar type')
                    result.append(dict(path=path, schema='context_scalar' if context else 'scalar', operand=value,
                        value=pin(canonical(raw))['sha256'], evidence_role=('inherited serialized evidence'
                            if value['role'] == 'entire_context_and_inner_error' else 'qualified own-source value')))
            pending.extend((value[k], path + [k]) for k in sorted(value, reverse=True))
    return result


def token(value, limit):
    if value is None:
        return 'undef', True, None
    string = str(value)
    number = type(value) is int or re.fullmatch(r'[012]', string) is not None
    complete = number or limit < 3 or len(string) <= limit
    prefix = string if complete else string[:limit - 3]
    if number:
        return string, True, string
    out = ['"']
    for character in prefix:
        codepoint = ord(character)
        if not 32 <= codepoint <= 126:
            out.extend(('\\x{', hex(codepoint)[2:], '}'))
        else:
            if character in ('"', '\\', '$', '@'):
                out.append('\\')
            out.append(character)
    out.append('"')
    if not complete:
        out.append('...')
    return ''.join(out), complete, prefix


def verify_source(source, product, selected):
    need(set(product) == {'scope', 'values', 'members'} and set(selected) == {'scope', 'profile', 'cases'},
         'closed whole scalar products')
    need(product['scope'] == selected['scope'] == SCOPE, 'source versus inherited/native scope')
    members = source_members(source)
    need(same(members, product['members']), 'complete independent scalar member/order/role/value allocation')
    values = {}
    for member in members:
        operand = member['operand']
        value = operand['value' if member['schema'] == 'scalar' else 'source_value']
        constructor = 'undef' if value is None else 'numeric literal' if type(value) is int else 'complete codepoint string'
        values[member['value']] = dict(value=value, constructor=constructor)
    need(same(values, product['values']), 'entire independently typed scalar value dictionary')
    need(same(selected['profile'], dict(MaxArgNums=0, MaxEvalLen=0, RefArgFormatter=None)), 'explicit selected public profile')
    cases = []
    for identifier in sorted(values):
        item = values[identifier]
        for limit in (64, 0):
            spelling, complete, prefix = token(item['value'], limit)
            cases.append(dict(id=identifier + ':' + str(limit), value_id=identifier, **item, limit=limit,
                display=dict(token=spelling, complete=complete, prefix=prefix)))
    need(same(cases, selected['cases']), 'independent complete constructor and display hypotheses')
    return dict(members=pin(canonical(members)), values=pin(canonical(values)), cases=pin(canonical(cases)), scope=SCOPE)


def verify_native(plan, receipt, driver):
    need(set(receipt) == {'command', 'status', 'stdout', 'stderr', 'inputs'}, 'closed actual public capture receipt')
    need(type(receipt['status']) is int and receipt['status'] == 0 and receipt['stderr'] == '', 'actual typed public capture success')
    import json
    native = json.loads(receipt['stdout'])
    need(set(native) == {'rows', 'runtime'} and set(native['runtime']) == {'perl','carp','json_pp'}
         and all(type(v) is str and v for v in native['runtime'].values()), 'whole current public runtime metadata')
    need([r['id'] for r in native['rows']] == [r['id'] for r in plan['cases']], 'complete ordered public scalar corpus')
    lines = driver.decode().splitlines()
    emitter_line = next(i for i, line in enumerate(lines, 1) if 'my $trace = emitter();' in line)
    caller_line = next(i for i, line in enumerate(lines, 1) if 'boundary($value)' in line)
    for case, row in zip(plan['cases'], native['rows'], strict=True):
        need(set(row) == {'id', 'trace', 'value', 'profile'}, 'closed complete native scalar observation')
        need(same(row['profile'], dict(**plan['profile'], MaxArgLen=case['limit'])), 'actual explicit current profile')
        expected = dict(defined=case['value'] is not None, codepoints=[] if case['value'] is None else list(map(ord, str(case['value']))))
        need(same(row['value'], expected), 'complete native constructed scalar value')
        expected_trace = ('scalar source fixture at docs/audits/observer-scalar-values-20261010/native.pl line ' + str(emitter_line) + '.\n'
            '\tmain::boundary(' + case['display']['token'] + ') called at docs/audits/observer-scalar-values-20261010/native.pl line ' + str(caller_line) + '\n')
        need(row['trace'] == expected_trace, 'whole source-generated public scalar header and trace')
    return dict(native=pin(receipt['stdout'].encode()), scope=SCOPE)

"""Preserve complete original scalar-child and ancestor acceptance contracts."""
import subprocess
from pathlib import Path
from common import BASE, REVISION, load, need, same, save

TASK = Path('docs/tasks/SEMANTIC-INTROSPECTION-MCP-FRONTIER.md')


def block(text, identifier):
    marker='- ID: `'+identifier+'`'
    need(text.count(marker)==1,'unique full scalar task authority')
    start=text.index(marker)
    end=text.find('\n- ID:',start+1)
    return text[start:end if end>=0 else None]


def contract(text):
    result={}
    for name in ('Goal','Acceptance','Children'):
        rows=[line for line in text.splitlines() if line.startswith('  '+name+':')]
        need(len(rows)==(1 if name!='Children' else int(bool(rows))),'whole unique task contract field')
        if rows:
            result[name]=rows[0]
    return result


def derive():
    owner=(BASE/'scope.txt').read_text().splitlines()[0]
    remaining=owner.rsplit('.',1)[0]
    values=remaining.rsplit('.',1)[0]
    headers=values.rsplit('.',1)[0]
    identifiers=[owner,remaining,values,headers,remaining+'.2',remaining+'.3']
    result=subprocess.run(['git','--no-replace-objects','show',REVISION+':'+str(TASK)],capture_output=True,text=True)
    need(result.returncode==0 and not result.stderr,'whole fixed scalar task source')
    current=TASK.read_text()
    bodies={identifier:block(result.stdout,identifier) for identifier in identifiers}
    for identifier,original in bodies.items():
        need(contract(block(current,identifier))==contract(original),'unchanged complete scalar-child and ancestor acceptance')
    return dict(revision=REVISION,task=str(TASK),original_bodies=bodies,
        scope='Whole unchanged source-value/header/remaining-scalar parent and child contracts only; scalar qualification closes no ancestor.')


if __name__ == '__main__':
    product=derive()
    if (BASE/'task-contracts.json').exists():
        need(same(product,load('task-contracts.json')),'whole immutable original task contracts')
    else:
        save('task-contracts.json',product)
    print('PASS complete unchanged scalar-child, ancestor and separately owned successor contracts.')
